#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *a[] = {"XXX", "OO ", "   "};
    assert(state(a) == WIN);
    const char *b[] = {"XOX", "XXO", "OXO"};
    assert(state(b) == DRAW);
    const char *c[] = {"OOO", "XX ", "X  "};
    assert(state(c) == WIN);
    const char *d[] = {"XXX", "OOO", "   "};
    assert(state(d) == INVALID);
    const char *e[] = {"   ", "   ", "   "};
    assert(state(e) == ONGOING);
    {
        const char *values[] = {"XOO", "X  ", "X  "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"OXO", " X ", " X "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"OOX", "  X", "  X"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"OXX", "OX ", "O  "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XOX", " OX", " O "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XXO", " XO", "  O"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XXX", "XOO", "O  "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"O  ", "XXX", " O "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {" OO", "O X", "XXX"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"OOO", "XXO", "XX "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XX ", "OOO", "X  "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XOX", " XX", "OOO"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XOO", " X ", "  X"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"O X", "OX ", "X  "};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"OXX", "OOX", "X O"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"  O", " OX", "OXX"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XXX", "XOO", "XOO"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XOX", "OXO", "XOX"};
        assert(state(values) == WIN);
    }
    {
        const char *values[] = {"XOX", "XXO", "OXO"};
        assert(state(values) == DRAW);
    }
    {
        const char *values[] = {"XXO", "OXX", "XOO"};
        assert(state(values) == DRAW);
    }
    {
        const char *values[] = {"   ", "X  ", "   "};
        assert(state(values) == ONGOING);
    }
    {
        const char *values[] = {"O  ", " X ", "   "};
        assert(state(values) == ONGOING);
    }
    {
        const char *values[] = {"X  ", " XO", "OX "};
        assert(state(values) == ONGOING);
    }
    return 0;
}
